1	/* ExamRadar site — all data is read from site/data/*.json, nothing is hardcoded. */
2	(function () {
3	  "use strict";
4	
5	  var COVERAGE_URL = "data/sample-coverage.json";
6	  var SESSIONS_URL = "data/qoder-sessions.json";
7	  var USAGE_URL = "data/usage-summary.json";
8	  var DEMO_VIDEO = "media/demo.mp4";
9	
10	  var LEVEL_LABEL = { covered: "已覆盖", thin: "薄弱", missing: "缺失" };
11	  var QUESTION_SNIPPET = 60;
12	
13	  function esc(s) {
14	    return String(s == null ? "" : s)
15	      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
16	      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
17	  }
18	
19	  function fmtNum(v, digits) {
20	    if (v == null || isNaN(v)) return "—";
21	    return Number(v).toFixed(digits == null ? 2 : digits);
22	  }
23	
24	  function fmtCredits(v) {
25	    if (v == null || isNaN(v)) return "—";
26	    return String(Math.round(v * 100) / 100);
27	  }
28	
29	  function renderMarkdown(text) {
30	    if (typeof marked === "undefined") return "<p>" + esc(text) + "</p>";
31	    try {
32	      return marked.parse(esc(text));
33	    } catch (e) {
34	      return "<p>" + esc(text) + "</p>";
35	    }
36	  }
37	
38	  /* paired backticks -> inline code; escape HTML first so the code span itself stays safe */
39	  function inlineCode(s) {
40	    return esc(s).replace(/`([^`]+)`/g, "<code>$1</code>");
41	  }
42	
43	  function levelBadge(level) {
44	    return level && LEVEL_LABEL[level]
45	      ? '<span class="badge ' + level + '">' + LEVEL_LABEL[level] + "</span>"
46	      : '<span class="badge unknown">未知</span>';
47	  }
48	
49	  /* ---------- screenshot placeholders: imgFallback lives in index.html <head> ---------- */
50	
51	  /* ---------- coverage snapshot ---------- */
52	  function loadCoverage() {
53	    return fetch(COVERAGE_URL)
54	      .then(function (r) { return r.ok ? r.json() : null; })
55	      .then(function (data) {
56	        var empty = !data || !Array.isArray(data.items) || data.items.length === 0;
57	        document.getElementById("radar-empty").hidden = !empty;
58	        document.getElementById("radar-chart").style.display = empty ? "none" : "";
59	        document.getElementById("blind-empty").hidden = !empty;
60	        if (empty) return;
61	        renderRadarMeta(data);
62	        renderRadarChart(data);
63	        renderBlindList(data);
64	      })
65	      .catch(function () {
66	        document.getElementById("radar-empty").hidden = false;
67	        document.getElementById("blind-empty").hidden = false;
68	      });
69	  }
70	
71	  function fmtLocalTime(iso) {
72	    var d = new Date(iso);
73	    if (isNaN(d.getTime())) return "";
74	    var pad = function (n) { return (n < 10 ? "0" : "") + n; };
75	    var local = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
76	      " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
77	    var off = -d.getTimezoneOffset();
78	    var sign = off >= 0 ? "+" : "-";
79	    var abs = Math.abs(off);
80	    var tz = "UTC" + sign + Math.floor(abs / 60) + (abs % 60 ? ":" + pad(abs % 60) : "");
81	    return local + "（访问者本地时间，" + tz + "）";
82	  }
83	
84	  function methodText(config) {
85	    if (!config) return "";
86	    if (config.term_ratio_covered != null || config.support_chars_covered != null ||
87	        config.min_body_chars != null) {
88	      var parts = [];
89	      if (config.term_ratio_covered != null)
90	        parts.push("考点词找到比例阈值 " + config.term_ratio_covered);
91	      if (config.support_chars_covered != null)
92	        parts.push("支撑正文字数阈值 " + config.support_chars_covered + " 字");
93	      if (config.min_body_chars != null)
94	        parts.push("计入支撑的最小段字数 " + config.min_body_chars + " 字");
95	      return "判定规则：一个考点词（含别名）都没找到 → 缺失；找到比例与支撑字数都达到阈值 → 已覆盖；其余 → 薄弱。" +
96	        "（" + parts.join("；") + "）";
97	    }
98	    var legacy = [];
99	    if (config.t_covered != null) legacy.push("covered ≥ " + config.t_covered);
100	    if (config.t_thin != null) legacy.push("thin ≥ " + config.t_thin);
101	    return legacy.length ? "判定阈值：" + legacy.join("，") : "";
102	  }
103	
104	  function renderRadarMeta(data) {
105	    var meta = document.getElementById("radar-meta");
106	    var bits = [];
107	    if (data.course_id) bits.push("课程 " + esc(data.course_id));
108	    if (Array.isArray(data.topics)) bits.push(data.topics.length + " 个知识点");
109	    if (data.created_at) bits.push("导出时间 " + esc(fmtLocalTime(data.created_at)));
110	    meta.textContent = bits.join(" · ");
111	    var th = document.getElementById("radar-method");
112	    if (th) th.textContent = methodText(data.config);
113	  }
114	
115	  function topicNames(data) {
116	    var names = {};
117	    (data.topics || []).forEach(function (t) { names[t.id] = t.name; });
118	    return names;
119	  }
120	
121	  /* axis labels wrap only at ：、与、（ and spaces — ASCII words (WAL / MVCC /
122	     3NF …) are never split. ： and （ are hard breaks; a line that would still
123	     overflow backtracks to the last soft break (after 与 or a space). */
124	  function wrapAxisLabel(name, maxLine) {
125	    var s = String(name == null ? "" : name);
126	    if (!s) return "";
127	    var tokens = s.match(/[A-Za-z0-9]+|[^A-Za-z0-9]/g) || [];
128	    var widthOf = function (t) {
129	      var w = 0;
130	      for (var i = 0; i < t.length; i++)
131	        w += t.charAt(i) === " " ? 0.3 : (t.charCodeAt(i) < 128 ? 0.55 : 1);
132	      return w;
133	    };
134	    var lines = [];
135	    var cur = "";
136	    var curW = 0;
137	    var mark = -1; /* index in cur where a soft break is allowed */
138	    var prevTok = "";
139	    tokens.forEach(function (tok) {
140	      if (tok === " ") {
141	        if (cur !== "") { cur += " "; curW += 0.3; mark = cur.length - 1; }
142	        return;
143	      }
144	      var w = widthOf(tok);
145	      if (cur !== "" && (tok === "（" || prevTok === "：")) {
146	        lines.push(cur);
147	        cur = ""; curW = 0; mark = -1;
148	      } else if (cur !== "" && curW + w > maxLine) {
149	        if (mark > 0) {
150	          lines.push(cur.slice(0, mark));
151	          cur = cur.slice(mark).replace(/^ /, "");
152	          curW = widthOf(cur);
153	          mark = -1;
154	        } /* else: no allowed break point — the container measurement is the real limit */
155	      }
156	      cur += tok;
157	      curW += w;
158	      if (tok === "：" || tok === "与") mark = cur.length;
159	      prevTok = tok;
160	    });
161	    if (cur !== "" || lines.length === 0) lines.push(cur);
162	    return lines.join("\n");
163	  }
164	
165	  function renderRadarChart(data) {
166	    if (typeof echarts === "undefined") return;
167	    var el = document.getElementById("radar-chart");
168	    var narrow = el.clientWidth < 420;
169	    var maxLine = narrow ? 8 : 11;
170	    var names = topicNames(data);
171	    var items = data.items;
172	    var indicators = items.map(function (it) {
173	      return { name: wrapAxisLabel(it.topic_name || names[it.topic_id] || it.topic_id || "", maxLine), max: 1 };
174	    });
175	    var coverage = items.map(function (it) {
176	      return it.coverage_score == null ? 0 : Math.max(0, Math.min(1, it.coverage_score));
177	    });
178	    var maxWeight = 0;
179	    items.forEach(function (it) {
180	      if (typeof it.exam_weight === "number" && it.exam_weight > maxWeight) maxWeight = it.exam_weight;
181	    });
182	    var weight = items.map(function (it) {
183	      if (maxWeight <= 0 || it.exam_weight == null) return 0;
184	      return Math.max(0, Math.min(1, it.exam_weight / maxWeight));
185	    });
186	    var chart = echarts.init(el, null, { renderer: "svg" });
187	    chart.setOption({
188	      tooltip: {
189	        trigger: "item",
190	        confine: true,
191	        formatter: function (p) {
192	          var i = p.dataIndex;
193	          var it = items[i];
194	          var lv = LEVEL_LABEL[it.coverage_level] || it.coverage_level || "未知";
195	          return esc(it.topic_name || names[it.topic_id] || it.topic_id) + "<br/>" +
196	            "覆盖度：" + fmtNum(it.coverage_score, 4) + "（" + lv + "）<br/>" +
197	            "往年分值：" + (it.exam_weight == null ? "—" : it.exam_weight + " 分");
198	        }
199	      },
200	      legend: { bottom: 8, data: ["覆盖度", "考试权重（按最大分值归一化）"], textStyle: { fontSize: 12 } },
201	      radar: {
202	        indicator: indicators,
203	        radius: narrow ? "46%" : "58%",
204	        center: ["50%", "46%"],
205	        axisName: { color: "#4a5568", fontSize: narrow ? 10 : 11, lineHeight: narrow ? 13 : 15 },
206	        splitArea: { areaStyle: { color: ["#ffffff", "#f4f7fc"] } }
207	      },
208	      series: [{
209	        type: "radar",
210	        data: [
211	          {
212	            name: "覆盖度",
213	            value: coverage,
214	            itemStyle: { color: "#2456d6" },
215	            areaStyle: { color: "rgba(36,86,214,0.18)" },
216	            lineStyle: { width: 2 }
217	          },
218	          {
219	            name: "考试权重（按最大分值归一化）",
220	            value: weight,
221	            itemStyle: { color: "#e67e22" },
222	            areaStyle: { color: "rgba(230,126,34,0.12)" },
223	            lineStyle: { width: 2, type: "dashed" }
224	          }
225	        ]
226	      }]
227	    });
228	    window.addEventListener("resize", function () { chart.resize(); });
229	  }
230	
231	  /* ---------- blind spot list (shared detail builder, table + mobile cards) ---------- */
232	  function sortedItems(data) {
233	    return data.items.slice().sort(function (a, b) {
234	      var sa = a.blind_spot_score == null ? -1 : a.blind_spot_score;
235	      var sb = b.blind_spot_score == null ? -1 : b.blind_spot_score;
236	      if (sa !== sb) return sb - sa;
237	      return String(a.topic_id || "").localeCompare(String(b.topic_id || ""), "en");
238	    });
239	  }
240	
241	  function chunkRef(c) {
242	    var parts = [];
243	    if (c.doc) parts.push(esc(c.doc));
244	    if (typeof c.page === "number") parts.push("第 " + c.page + " 页");
245	    if (c.heading) parts.push(esc(c.heading));
246	    return parts.join(" · ");
247	  }
248	
249	  function termsHtml(it) {
250	    if (!Array.isArray(it.terms) || it.terms.length === 0) return "";
251	    var lis = it.terms.map(function (t) {
252	      var alias = Array.isArray(t.aliases) && t.aliases.length
253	        ? '<span class="term-alias">（别名：' + t.aliases.map(esc).join("、") + "）</span>" : "";
254	      var found = t.found
255	        ? '<span class="term-found">✓ 找到</span>'
256	        : '<span class="term-miss">✗ 没找到</span>';
257	      var chunks = "";
258	      if (t.found && Array.isArray(t.chunks) && t.chunks.length) {
259	        var shown = t.chunks.slice(0, 3).map(function (c) {
260	          return "<div>" + chunkRef(c) + "</div>";
261	        }).join("");
262	        if (t.chunks.length > 3)
263	          shown += '<div class="muted">…等共 ' + t.chunks.length + " 段</div>";
264	        chunks = '<div class="term-chunks">' + shown + "</div>";
265	      }
266	      return '<li><div class="term-line"><span class="term-name">' + esc(t.term) + "</span>" +
267	        alias + found + "</div>" + chunks + "</li>";
268	    });
269	    return '<h4 style="margin-top:14px">考点词明细</h4><ul class="term-list">' + lis.join("") + "</ul>";
270	  }
271	
272	  function supportHtml(it) {
273	    if (it.support_chunks == null && it.support_chars == null) return "";
274	    var chunks = it.support_chunks == null ? "—" : it.support_chunks;
275	    var chars = it.support_chars == null ? "—" : it.support_chars;
276	    return '<p class="muted" style="font-size:13px;margin:8px 0 0">支撑正文：' +
277	      chunks + " 段，共 " + chars + " 字</p>";
278	  }
279	
280	  function evidenceHtml(it) {
281	    var ev = it.best_evidence;
282	    if (!ev) return "";
283	    var html = '<h4 style="margin-top:14px">最强证据</h4><div class="evidence">';
284	    if (ev.content) html += '<div class="ev-content">' + renderMarkdown(ev.content) + "</div>";
285	    var parts = [];
286	    if (ev.document_name) parts.push(esc(ev.document_name));
287	    if (typeof ev.page === "number") parts.push("第 " + ev.page + " 页");
288	    if (ev.heading) parts.push(esc(ev.heading));
289	    var scores = [];
290	    if (ev.semantic_score != null) scores.push("语义分 " + fmtNum(ev.semantic_score, 4));
291	    if (ev.keyword_score != null) scores.push("关键词分 " + fmtNum(ev.keyword_score, 4));
292	    html += '<div class="ev-meta">' + parts.join(" · ") +
293	      (scores.length ? (parts.length ? " · " : "") + scores.join(" · ") : "") + "</div></div>";
294	    return html;
295	  }
296	
297	  function questionsHtml(it) {
298	    if (!Array.isArray(it.exam_questions) || it.exam_questions.length === 0) return "";
299	    var qs = it.exam_questions.map(function (q, qi) {
300	      var line = "第 " + esc(q.question_no) + " 题 · " +
301	        (q.points == null ? "分值未知" : q.points + " 分");
302	      if (Array.isArray(q.matched_terms) && q.matched_terms.length)
303	        line += " · 命中考点词：" + q.matched_terms.map(esc).join("、");
304	      if (q.similarity != null) line += " · 相似度 " + fmtNum(q.similarity, 3);
305	      var content = "";
306	      if (q.content) {
307	        var text = String(q.content);
308	        var snippet = text.slice(0, QUESTION_SNIPPET);
309	        var expandable = text.length > QUESTION_SNIPPET;
310	        var shortText = snippet + (expandable ? "…" : "");
311	        content = '<div class="q-content"><span class="q-snippet" data-short="' +
312	          esc(shortText) + '" data-full="' + esc(text) + '">' + esc(shortText) + "</span>";
313	        if (expandable)
314	          content += ' <button class="q-toggle" data-q="' + qi + '">展开原文</button>';
315	        content += "</div>";
316	      }
317	      return '<div class="q-item"><div class="q-line">' + line + "</div>" + content + "</div>";
318	    }).join("");
319	    return '<h4 style="margin-top:14px">关联的往年试题</h4>' + qs;
320	  }
321	
322	  function detailHtml(it) {
323	    var html = '<div class="detail-box">';
324	    if (it.reason)
325	      html += '<h4>判定理由</h4><p class="reason-text" style="margin-top:0">' + esc(it.reason) + "</p>";
326	    html += supportHtml(it) + termsHtml(it) + evidenceHtml(it) + questionsHtml(it);
327	    if (!it.reason && !it.best_evidence && !it.terms &&
328	        !(Array.isArray(it.exam_questions) && it.exam_questions.length))
329	      html += '<p class="muted" style="margin:0">这条记录缺少证据与试题数据。</p>';
330	    html += "</div>";
331	    return html;
332	  }
333	
334	  function toggleQuestion(btn) {
335	    var item = btn.closest(".q-item");
336	    var snippet = item.querySelector(".q-snippet");
337	    if (!snippet) return;
338	    var showing = btn.textContent === "收起原文";
339	    btn.textContent = showing ? "展开原文" : "收起原文";
340	    snippet.textContent = showing ? snippet.getAttribute("data-short") : snippet.getAttribute("data-full");
341	  }
342	
343	  function renderBlindList(data) {
344	    var names = topicNames(data);
345	    var items = sortedItems(data);
346	
347	    var tbody = document.getElementById("blind-tbody");
348	    var rowsHtml = "";
349	    var cardsHtml = "";
350	    items.forEach(function (it, idx) {
351	      var name = it.topic_name || names[it.topic_id] || it.topic_id || "—";
352	      var cov = fmtNum(it.coverage_score, 4);
353	      var weight = it.exam_weight == null ? "—" : it.exam_weight;
354	      var blind = fmtNum(it.blind_spot_score);
355	
356	      rowsHtml +=
357	        '<tr class="row-main" data-idx="' + idx + '">' +
358	        "<td>" + esc(name) + "</td>" +
359	        "<td>" + levelBadge(it.coverage_level) + "</td>" +
360	        '<td class="num">' + cov + "</td>" +
361	        '<td class="num">' + weight + "</td>" +
362	        '<td class="num">' + blind + "</td>" +
363	        '<td class="exp muted" style="text-align:center">&#9656;</td></tr>' +
364	        '<tr class="row-detail" data-detail="' + idx + '" hidden><td colspan="6">' + detailHtml(it) + "</td></tr>";
365	
366	      cardsHtml +=
367	        '<div class="blind-card"><div class="bc-head" data-idx="' + idx + '">' +
368	        '<span class="bc-name">' + esc(name) + "</span>" + levelBadge(it.coverage_level) +
369	        '<span class="exp muted">&#9656;</span></div>' +
370	        '<div class="bc-stats">' +
371	        "<div><b>" + cov + '</b>覆盖度</div>' +
372	        "<div><b>" + weight + '</b>往年分值</div>' +
373	        "<div><b>" + blind + '</b>盲区分值</div>' +
374	        "</div><div class=\"bc-detail\" data-idx=\"" + idx + "\" hidden>" + detailHtml(it) + "</div></div>";
375	    });
376	    tbody.innerHTML = rowsHtml;
377	    document.getElementById("blind-cards").innerHTML = cardsHtml;
378	
379	    function toggle(root, idx) {
380	      var head = root.querySelector('[data-idx="' + idx + '"]');
381	      var detail = root.querySelector('.row-detail[data-detail="' + idx + '"], .bc-detail[data-idx="' + idx + '"]');
382	      var open = !detail.hidden;
383	      detail.hidden = open;
384	      head.classList.toggle("open", !open);
385	      var exp = head.querySelector(".exp");
386	      if (exp) exp.innerHTML = open ? "&#9656;" : "&#9662;";
387	    }
388	
389	    tbody.addEventListener("click", function (e) {
390	      if (e.target.closest(".q-toggle")) { toggleQuestion(e.target.closest(".q-toggle")); return; }
391	      var tr = e.target.closest("tr.row-main");
392	      if (tr) toggle(tbody, tr.getAttribute("data-idx"));
393	    });
394	    var cards = document.getElementById("blind-cards");
395	    cards.addEventListener("click", function (e) {
396	      if (e.target.closest(".q-toggle")) { toggleQuestion(e.target.closest(".q-toggle")); return; }
397	      var head = e.target.closest(".bc-head");
398	      if (head) toggle(cards, head.getAttribute("data-idx"));
399	    });
400	  }
401	
402	  /* ---------- qoder sessions ---------- */
403	  function loadSessions() {
404	    return fetch(SESSIONS_URL)
405	      .then(function (r) { return r.ok ? r.json() : null; })
406	      .then(function (data) {
407	        var wrap = document.getElementById("sessions-body");
408	        var totalRow = document.getElementById("sessions-total");
409	        if (!data || !Array.isArray(data.rows) || data.rows.length === 0) {
410	          wrap.innerHTML = '<tr><td colspan="6" class="muted">会话数据不可用。</td></tr>';
411	          totalRow.hidden = true;
412	          return;
413	        }
414	        var html = "";
415	        var cardsHtml = "";
416	        data.rows.forEach(function (r) {
417	          var modelCls = /GLM/i.test(r.model || "") ? "model-tag glm" : "model-tag";
418	          html +=
419	            "<tr>" +
420	            "<td>" + esc(r.id == null ? "—" : r.id) + "</td>" +
421	            '<td class="title-cell">' + inlineCode(r.title || "—") + "</td>" +
422	            "<td class=" + JSON.stringify(modelCls) + ">" + esc(r.model || "—") + "</td>" +
423	            '<td class="num">' + (r.turns == null ? "—" : r.turns) + "</td>" +
424	            "<td>" + esc(r.duration || "—") + "</td>" +
425	            '<td class="num">' + fmtCredits(r.credits) + "</td>" +
426	            "</tr>";
427	          cardsHtml +=
428	            '<div class="session-card">' +
429	            '<div class="sc-head"><span class="sc-id">会话 ' + esc(r.id == null ? "—" : r.id) + "</span>" +
430	            '<span class="' + modelCls + '">' + esc(r.model || "—") + "</span></div>" +
431	            '<div class="sc-title">' + inlineCode(r.title || "—") + "</div>" +
432	            '<div class="sc-stats">' +
433	            "<div><b>" + (r.turns == null ? "—" : r.turns) + "</b>轮数</div>" +
434	            "<div><b>" + esc(r.duration || "—") + "</b>耗时</div>" +
435	            "<div><b>" + fmtCredits(r.credits) + "</b>Credits</div>" +
436	            "</div></div>";
437	        });
438	        wrap.innerHTML = html;
439	        var t = data.totals || {};
440	        document.getElementById("total-rows").textContent = t.rows != null ? t.rows : "—";
441	        document.getElementById("total-turns").textContent = t.turns != null ? t.turns : "—";
442	        document.getElementById("total-credits").textContent = t.credits != null ? fmtCredits(t.credits) : "—";
443	        cardsHtml += '<div class="session-total">合计 ' + (t.rows != null ? t.rows : "—") +
444	          " 条记录 · " + (t.turns != null ? t.turns : "—") +
445	          " 轮 · " + (t.credits != null ? fmtCredits(t.credits) : "—") + " Credits</div>";
446	        document.getElementById("sessions-cards").innerHTML = cardsHtml;
447	      })
448	      .catch(function () {
449	        document.getElementById("sessions-body").innerHTML =
450	          '<tr><td colspan="6" class="muted">会话数据不可用。</td></tr>';
451	        document.getElementById("sessions-total").hidden = true;
452	      });
453	  }
454	
455	  /* ---------- usage summary: three optional blocks ---------- */
456	  function statCard(value, label, unit) {
457	    return '<div class="stat"><div class="v">' + (value == null ? "—" : esc(value)) +
458	      '</div><div class="k">' + esc(label) + (unit && value != null ? " · " + esc(unit) : "") + "</div></div>";
459	  }
460	
461	  function srcLine(obj) {
462	    var parts = [];
463	    if (obj && obj.source) parts.push("来源：" + esc(obj.source));
464	    if (obj && obj.exported_at) parts.push("导出时间：" + esc(obj.exported_at));
465	    return parts.length ? '<p class="usage-src">' + parts.join(" · ") + "</p>" : "";
466	  }
467	
468	  function loadUsage() {
469	    return fetch(USAGE_URL)
470	      .then(function (r) { return r.ok ? r.json() : null; })
471	      .then(function (data) {
472	        var collecting = document.getElementById("usage-collecting");
473	        var filled = document.getElementById("usage-filled");
474	        if (!data || data.status === "collecting") return;
475	        var blocks = [];
476	
477	        var site = data.site_stats;
478	        if (site && (site.pv != null || site.uv != null)) {
479	          var period = site.period ? "（" + esc(site.period) + "）" : "";
480	          blocks.push('<div class="usage-block"><h3>Qoder Sites 访问统计' + period + "</h3>" +
481	            '<div class="usage-stats">' +
482	            statCard(site.pv, "页面浏览 PV") + statCard(site.uv, "独立访客 UV") +
483	            "</div>" + srcLine(site) + "</div>");
484	        }
485	
486	        var usage = data.usage || {
487	          usage_days: data.usage_days, study_sessions: data.study_sessions,
488	          questions_answered: data.questions_answered, total_minutes: data.total_minutes,
489	          source: data.source, exported_at: data.exported_at
490	        };
491	        if (usage && (usage.usage_days != null || usage.study_sessions != null ||
492	            usage.questions_answered != null || usage.total_minutes != null)) {
493	          blocks.push('<div class="usage-block"><h3>使用记录汇总</h3><div class="usage-stats">' +
494	            statCard(usage.usage_days, "使用天数", "天") +
495	            statCard(usage.study_sessions, "学习会话数", "次") +
496	            statCard(usage.questions_answered, "做题数", "题") +
497	            statCard(usage.total_minutes, "累计学习时长", "分钟") +
498	            "</div>" + srcLine(usage) + "</div>");
499	        }
500	
501	        var feedback = data.feedback;
502	        if (Array.isArray(feedback) && feedback.length) {
503	          var quotes = feedback.map(function (f) {
504	            return "<li>" + esc(typeof f === "string" ? f : (f.quote || "")) + "</li>";
505	          }).join("");
506	          var meta = Array.isArray(feedback) && feedback[0] && typeof feedback[0] === "object"
507	            ? srcLine(feedback[0]) : "";
508	          blocks.push('<div class="usage-block"><h3>用户反馈</h3>' +
509	            '<ul class="feedback-list">' + quotes + "</ul>" + meta + "</div>");
510	        }
511	
512	        if (!blocks.length) return;
513	        collecting.hidden = true;
514	        filled.hidden = false;
515	        document.getElementById("usage-blocks").innerHTML = blocks.join("");
516	      })
517	      .catch(function () { /* keep collecting state */ });
518	  }
519	
